package com.fixmer.mared;
import com.fixmer.genesis.technology.scripts.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import java.util.jar.*;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
public class ProjectDependenciesIntegrationTest {
 private static ProjectDependencies.Config empty(){return new ProjectDependencies.Config(List.of(),List.of(),false);}
 private static ProjectDependencies.Dependency library(ProjectDependencies.Mode mode){return ProjectDependencies.Dependency.library(mode,"org.example:lib:1.2.3");}
 private static SourceProjects store(boolean neo)throws Exception{var s=new SourceProjects(Files.createTempDirectory("dependency-projects-"));s.createEmpty("demo");if(neo){for(var e:NeoForgeProjectTemplate.files("demo").entrySet())if(!e.getKey().equals("genesis-project.properties"))s.createFile("demo",e.getKey(),e.getValue());}else s.initializeGradle("demo");return s;}
 @Test public void schemaRoundTripsWithoutExecutingOrDownloading()throws Exception{var c=empty().add(library(ProjectDependencies.Mode.LIBRARY)).repository("https://maven.example.test/releases");assertEquals(c,ProjectDependencies.parse(ProjectDependencies.encode(c)));var properties=new Properties();properties.load(new StringReader(ProjectDependencies.encode(c)));assertTrue(properties.containsKey("dependency.0")&&properties.containsKey("repository.0"));assertThrows(IOException.class,()->ProjectDependencies.parse(ProjectDependencies.encode(c).replace("dependency.0=","dependency.1=")));assertThrows(IOException.class,()->ProjectDependencies.parse(ProjectDependencies.encode(c)+"dependency.0=LIBRARY|org.example:other:1||||\n"));assertEquals(empty(),ProjectDependencies.parse(""));assertThrows(IOException.class,()->ProjectDependencies.parse("format=1\nformat=1\n"));assertThrows(IOException.class,()->ProjectDependencies.parse("format=2\n"));assertThrows(IOException.class,()->ProjectDependencies.parse("format=1\nlocalLibraries=maybe\n"));}
 @Test public void invalidCoordinatesUrlsAndInjectionAreRejected(){for(String text:List.of("g:a:+","g:a:latest.release","g:a:1-SNAPSHOT","g:a:1');exit()//","g:a:1|MOD","g:a:1\n"))assertFalse(ProjectDependencies.validCoordinate(text));assertTrue(ProjectDependencies.validCoordinate("org.test:api:1.2:neoforge"));for(String url:List.of("http://example.test/repo","https://user:password@example.test/repo","https://example.test/repo?x=1","https://example.test/';oops"))assertFalse(ProjectDependencies.validRepository(url));assertTrue(ProjectDependencies.validRange("[1.0,)"));assertFalse(ProjectDependencies.validRange("\";oops"));}
 @Test public void duplicateArtifactsAndModIdsAreRefused(){var c=empty().add(library(ProjectDependencies.Mode.LIBRARY));assertThrows(IllegalArgumentException.class,()->c.add(library(ProjectDependencies.Mode.COMPILE_ONLY)));var d=new ProjectDependencies.Dependency(ProjectDependencies.Mode.MOD,"g:first:1","othermod","[1,)","required","BOTH");assertThrows(IllegalArgumentException.class,()->empty().add(d).add(new ProjectDependencies.Dependency(ProjectDependencies.Mode.MOD,"g:second:1","othermod","[1,)","optional","CLIENT")));}
 @Test public void normalGradleProjectsSupportLibrariesButNotModEmbedding()throws Exception{var s=store(false);var state=s.dependencyState("demo");var c=empty().add(library(ProjectDependencies.Mode.LIBRARY)).add(ProjectDependencies.Dependency.library(ProjectDependencies.Mode.COMPILE_ONLY,"g:api:2"));s.setDependencies("demo",state,c);String script=s.read("demo",ProjectDependencies.SCRIPT);assertTrue(script.contains("implementation 'org.example:lib:1.2.3'"));assertTrue(script.contains("compileOnly 'g:api:2'"));assertThrows(IOException.class,()->s.setDependencies("demo",s.dependencyState("demo"),empty().add(library(ProjectDependencies.Mode.EMBED))));}
 @Test public void requiredAndOptionalModsWriteCorrectMetadata()throws Exception{var s=store(true);var c=empty().add(new ProjectDependencies.Dependency(ProjectDependencies.Mode.MOD,"example:core:2","coremod","[2,3)","required","BOTH")).add(new ProjectDependencies.Dependency(ProjectDependencies.Mode.MOD,"example:api:1","optionalmod","[1,)","optional","CLIENT"));s.setDependencies("demo",s.dependencyState("demo"),c);String toml=s.read("demo",ProjectDependencies.TOML),script=s.read("demo",ProjectDependencies.SCRIPT);assertTrue(toml.contains("[[dependencies.demo]]\nmodId=\"coremod\"\ntype=\"required\""));assertTrue(toml.contains("side=\"CLIENT\""));assertTrue(script.contains("compileOnly 'example:api:1'"));assertTrue(script.contains("implementation 'example:core:2'"));assertFalse(script.contains("jarJar("));}
 @Test public void embeddedLibrariesHaveExactRangeRuntimeAndBuildTask()throws Exception{var s=store(true);s.setDependencies("demo",s.dependencyState("demo"),empty().add(library(ProjectDependencies.Mode.EMBED)));String text=s.read("demo",ProjectDependencies.SCRIPT);assertTrue(text.contains("jarJar('org.example:lib:[1.2.3]') { version { prefer '1.2.3'"));assertTrue(text.contains("runtime 'org.example:lib:1.2.3'"));assertTrue(text.contains("dependsOn tasks.named('jarJar')"));}
 @Test public void repeatedUpdatesAndRemovalPreserveManualConfiguration()throws Exception{var s=store(true);String initial=s.read("demo","build.gradle");String toml=s.read("demo",ProjectDependencies.TOML);var c=empty().add(library(ProjectDependencies.Mode.LIBRARY));s.setDependencies("demo",s.dependencyState("demo"),c);var first=s.dependencyState("demo");s.setDependencies("demo",first,c);assertEquals(first,s.dependencyState("demo"));s.setDependencies("demo",first,empty());assertTrue(s.read("demo","build.gradle").startsWith(initial));assertTrue(s.read("demo",ProjectDependencies.TOML).startsWith(toml));assertFalse(s.read("demo",ProjectDependencies.SCRIPT).contains("org.example:lib"));}
 @Test public void staleSnapshotsCannotWriteAnyFile()throws Exception{var s=store(true);var before=s.dependencyState("demo");s.save("demo","build.gradle",before.files().get("build.gradle"),before.files().get("build.gradle")+"// external\n");var expected=s.dependencyState("demo");assertThrows(IOException.class,()->s.setDependencies("demo",before,empty().add(library(ProjectDependencies.Mode.LIBRARY))));assertEquals(expected,s.dependencyState("demo"));}
 @Test public void editedManagedScriptsAndMetadataAreNotOverwritten()throws Exception{var s=store(true);var c=empty().add(new ProjectDependencies.Dependency(ProjectDependencies.Mode.MOD,"g:core:1","othermod","[1,)","required","BOTH"));s.setDependencies("demo",s.dependencyState("demo"),c);for(String file:List.of(ProjectDependencies.SCRIPT,ProjectDependencies.TOML,"build.gradle")){var before=s.dependencyState("demo");String text=before.files().get(file);String edit=file.equals(ProjectDependencies.TOML)?text.replace("ordering=\"NONE\"","ordering=\"AFTER\""):file.equals("build.gradle")?text.replace("apply from:","// edit\napply from:"):text+"// edit\n";s.save("demo",file,text,edit);var modified=s.dependencyState("demo");assertThrows(IOException.class,()->s.setDependencies("demo",modified,c));assertEquals(modified,s.dependencyState("demo"));s.save("demo",file,edit,text);}}
 @Test public void selfAndManuallyDeclaredDependenciesAreRefused()throws Exception{var s=store(true);var state=s.dependencyState("demo");assertThrows(IOException.class,()->s.setDependencies("demo",state,empty().add(new ProjectDependencies.Dependency(ProjectDependencies.Mode.MOD,"g:demo:1","demo","[1,)","required","BOTH"))));String build=state.files().get("build.gradle");s.save("demo","build.gradle",build,build+"dependencies { implementation 'org.example:lib:1.2.3' }\n");assertThrows(IOException.class,()->s.setDependencies("demo",s.dependencyState("demo"),empty().add(library(ProjectDependencies.Mode.LIBRARY))));}
 @Test public void localJarsAreValidatedAndConnectedToNeoForgeRuns()throws Exception{var s=store(true);Path dir=s.projectDirectory("demo").resolve("libraries");Files.createDirectories(dir);Path jar=dir.resolve("bad.jar");Files.writeString(jar,"not zip");var state=s.dependencyState("demo");var c=new ProjectDependencies.Config(List.of(),List.of(),true);assertThrows(IOException.class,()->s.setDependencies("demo",state,c));assertEquals(state,s.dependencyState("demo"));Files.delete(jar);try(var out=new JarOutputStream(Files.newOutputStream(dir.resolve("good.jar")))){out.putNextEntry(new JarEntry("readme.txt"));out.write(new byte[]{1});out.closeEntry();}s.setDependencies("demo",state,c);assertTrue(s.read("demo",ProjectDependencies.SCRIPT).contains("runtime project.files"));}
 @Test public void exportIncludesConfigurationAndStandaloneBuildWiring()throws Exception{var s=store(true);s.setDependencies("demo",s.dependencyState("demo"),empty().add(library(ProjectDependencies.Mode.EMBED)).repository("https://maven.example.test/releases"));try(var z=new ZipFile(s.exportProject("demo",Map.of()).toFile())){assertTrue(z.stream().anyMatch(e->e.getName().endsWith(ProjectDependencies.CONFIG)));assertTrue(z.stream().anyMatch(e->e.getName().endsWith(ProjectDependencies.SCRIPT)));}}
 @Test public void repositoriesCanBeRemovedAndKotlinOnlyIsExplicitlyRefused()throws Exception{var s=store(false);var c=empty().repository("https://maven.example.test/releases");s.setDependencies("demo",s.dependencyState("demo"),c);s.setDependencies("demo",s.dependencyState("demo"),empty());assertFalse(s.read("demo",ProjectDependencies.SCRIPT).contains("maven.example.test"));assertThrows(IOException.class,()->ProjectDependencies.render(new ProjectDependencies.State(Map.of("build.gradle.kts","plugins { java }")),empty()));}
 @Test public void enablingLocalLibrariesCreatesTheirFolder()throws Exception{var s=store(true);Path folder=s.projectDirectory("demo").resolve("libraries");assertFalse(Files.exists(folder));s.setDependencies("demo",s.dependencyState("demo"),new ProjectDependencies.Config(List.of(),List.of(),true));assertTrue(Files.isDirectory(folder));}
 @Test public void cancellationAfterWritesRestoresOriginalBytesAndRemovesNewFiles()throws Exception{var s=store(true);Path build=s.projectDirectory("demo").resolve("build.gradle");Files.writeString(build,s.read("demo","build.gradle").replace("\n","\r\n"));byte[] original=Files.readAllBytes(build);var state=s.dependencyState("demo");int[] calls={0};assertThrows(IOException.class,()->s.setDependencies("demo",state,empty().add(library(ProjectDependencies.Mode.EMBED)),()->++calls[0]>=4));assertEquals(state,s.dependencyState("demo"));assertTrue(Arrays.equals(original,Files.readAllBytes(build)));assertFalse(Files.exists(s.projectDirectory("demo").resolve(ProjectDependencies.CONFIG)));assertFalse(Files.exists(s.projectDirectory("demo").resolve(ProjectDependencies.SCRIPT)));}
 public static void main(String[]args)throws Exception{var t=new ProjectDependenciesIntegrationTest();t.schemaRoundTripsWithoutExecutingOrDownloading();t.invalidCoordinatesUrlsAndInjectionAreRejected();t.duplicateArtifactsAndModIdsAreRefused();t.normalGradleProjectsSupportLibrariesButNotModEmbedding();t.requiredAndOptionalModsWriteCorrectMetadata();t.embeddedLibrariesHaveExactRangeRuntimeAndBuildTask();t.repeatedUpdatesAndRemovalPreserveManualConfiguration();t.staleSnapshotsCannotWriteAnyFile();t.editedManagedScriptsAndMetadataAreNotOverwritten();t.selfAndManuallyDeclaredDependenciesAreRefused();t.localJarsAreValidatedAndConnectedToNeoForgeRuns();t.exportIncludesConfigurationAndStandaloneBuildWiring();t.repositoriesCanBeRemovedAndKotlinOnlyIsExplicitlyRefused();t.enablingLocalLibrariesCreatesTheirFolder();t.cancellationAfterWritesRestoresOriginalBytesAndRemovesNewFiles();System.out.println("Project dependency integration scenarios passed: 15; production storage/rendering, Gradle wiring, required/optional mods, Jar-in-Jar declarations, conflict safety, local archive validation and export; no actual Gradle resolution or NeoForge runtime");}
}
